CREATE SCHEMA IF NOT EXISTS shiliu;

REVOKE ALL ON SCHEMA public FROM PUBLIC;

CREATE EXTENSION vector WITH SCHEMA shiliu VERSION '0.8.7';

CREATE TABLE shiliu."asr_jobs" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "video_id" bigint NOT NULL,
    "provider" text NOT NULL,
    "model" text NOT NULL,
    "trigger_mode" text NOT NULL,
    "status" text NOT NULL DEFAULT 'pending',
    "task_id" text,
    "remote_file_url" text,
    "result_url" text,
    "audio_path" text,
    "attempt_count" bigint NOT NULL DEFAULT 0,
    "next_retry_at" timestamptz,
    "last_error_code" text,
    "last_error_message" text,
    "submitted_at" timestamptz,
    "completed_at" timestamptz,
    "created_at" timestamptz NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "workspace_id" text NOT NULL,
    "lease_owner" text,
    "lease_until" timestamptz,
    "lease_epoch" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("video_id")
);

CREATE INDEX "idx_asr_jobs_due" ON shiliu."asr_jobs" ("workspace_id", "status", "next_retry_at");

CREATE TABLE shiliu."events" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_type" text NOT NULL,
    "video_id" bigint,
    "payload_json" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "status" text NOT NULL DEFAULT 'pending',
    "created_at" timestamptz NOT NULL,
    "processed_at" timestamptz,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "idx_events_status" ON shiliu."events" ("workspace_id", "status", "created_at");

CREATE TABLE shiliu."favorite_sources" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "platform" text NOT NULL DEFAULT 'bilibili',
    "original_url" text NOT NULL DEFAULT '',
    "account_id" bigint,
    "account_name" text NOT NULL DEFAULT '',
    "folder_id" bigint NOT NULL,
    "folder_title" text NOT NULL DEFAULT '',
    "media_count" bigint NOT NULL DEFAULT 0,
    "status" text NOT NULL DEFAULT 'active',
    "history_policy" text NOT NULL DEFAULT 'future_only',
    "history_limit" bigint,
    "baseline_initialized" boolean NOT NULL DEFAULT false,
    "cooldown_until" timestamptz,
    "last_sync_at" timestamptz,
    "last_error_code" text,
    "last_error_message" text,
    "sort_order" bigint NOT NULL DEFAULT 0,
    "created_at" timestamptz NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "history_cutoff_time" bigint,
    "discovery_complete" boolean NOT NULL DEFAULT false,
    "last_snapshot_complete" boolean NOT NULL DEFAULT false,
    "history_updated_at" timestamptz,
    "workspace_id" text NOT NULL,
    "lease_owner" text,
    "lease_until" timestamptz,
    "lease_epoch" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("workspace_id","platform","folder_id"),
    UNIQUE ("workspace_id","id")
);

CREATE INDEX "idx_sources_status" ON shiliu."favorite_sources" ("workspace_id", "status", "cooldown_until");

CREATE TABLE shiliu."pipeline_stages" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "video_id" bigint NOT NULL,
    "stage_name" text NOT NULL,
    "status" text NOT NULL,
    "attempt_count" bigint NOT NULL DEFAULT 0,
    "next_retry_at" timestamptz,
    "last_error_code" text,
    "last_error_message" text,
    "provider" text,
    "model" text,
    "prompt_version" text,
    "started_at" timestamptz,
    "completed_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "profile" text NOT NULL DEFAULT 'formal',
    "thinking_enabled" boolean,
    "reasoning_effort" text,
    "decision" text,
    "change_reasons_json" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "elapsed_seconds" double precision,
    "workspace_id" text NOT NULL,
    "lease_owner" text,
    "lease_until" timestamptz,
    "lease_epoch" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("video_id","stage_name")
);

CREATE INDEX "idx_stages_due" ON shiliu."pipeline_stages" ("workspace_id", "status", "next_retry_at");

CREATE TABLE shiliu."seen_items" (
    "platform" text NOT NULL,
    "source_id" text NOT NULL,
    "part" bigint NOT NULL DEFAULT 1,
    "is_baseline" boolean NOT NULL DEFAULT false,
    "first_seen_at" timestamptz NOT NULL,
    "last_seen_at" timestamptz NOT NULL,
    "removed_at" timestamptz,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("workspace_id","platform","source_id","part")
);

CREATE TABLE shiliu."sync_runs" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mode" text NOT NULL,
    "status" text NOT NULL,
    "started_at" timestamptz NOT NULL,
    "finished_at" timestamptz,
    "current_count" bigint NOT NULL DEFAULT 0,
    "discovered_count" bigint NOT NULL DEFAULT 0,
    "processed_count" bigint NOT NULL DEFAULT 0,
    "failed_count" bigint NOT NULL DEFAULT 0,
    "error_summary" text,
    "scope_source_id" bigint,
    "current_phase" text,
    "current_video_id" bigint,
    "history_pending_count" bigint NOT NULL DEFAULT 0,
    "message" text,
    "heartbeat_at" timestamptz,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE shiliu."taxonomy_classification_cards" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "snapshot_id" bigint NOT NULL,
    "content_key" text NOT NULL,
    "video_id" bigint,
    "platform" text NOT NULL,
    "source_content_id" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "evidence_level" text NOT NULL,
    "discovery_eligible" boolean NOT NULL,
    "selected_revision" text,
    "stored_card_json" jsonb NOT NULL,
    "discovery_view_json" jsonb NOT NULL,
    "card_hash" text NOT NULL,
    "discovery_view_hash" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("snapshot_id","content_key"),
    UNIQUE ("snapshot_id","ordinal")
);

CREATE INDEX "idx_taxonomy_cards_snapshot" ON shiliu."taxonomy_classification_cards" ("workspace_id", "snapshot_id", "ordinal");

CREATE TABLE shiliu."taxonomy_corpus_snapshots" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "selected_source_ids_json" jsonb NOT NULL,
    "membership_count" bigint NOT NULL,
    "content_count" bigint NOT NULL,
    "duplicate_memberships_merged" bigint NOT NULL,
    "discovery_eligible_count" bigint NOT NULL,
    "trial_assignment_only_count" bigint NOT NULL,
    "evidence_counts_json" jsonb NOT NULL,
    "snapshot_hash" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    "frozen_at" timestamptz NOT NULL,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("workspace_id","snapshot_hash"),
    UNIQUE ("workspace_id","id")
);

CREATE TABLE shiliu."taxonomy_runs" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "run_kind" text NOT NULL DEFAULT 'production',
    "status" text NOT NULL DEFAULT 'pending',
    "current_stage" text,
    "corpus_snapshot_id" bigint,
    "engine" text,
    "engine_version" text,
    "parameters_json" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "search_enabled" boolean NOT NULL DEFAULT false,
    "created_at" timestamptz NOT NULL,
    "started_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "completed_at" timestamptz,
    "last_error_code" text,
    "last_error_message" text,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("workspace_id","id")
);

CREATE INDEX "idx_taxonomy_runs_status" ON shiliu."taxonomy_runs" ("workspace_id", "status", "updated_at");

CREATE TABLE shiliu."taxonomy_stage_runs" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "run_id" bigint NOT NULL,
    "stage_name" text NOT NULL,
    "unit_key" text NOT NULL DEFAULT 'main',
    "status" text NOT NULL DEFAULT 'pending',
    "attempt_count" bigint NOT NULL DEFAULT 0,
    "next_retry_at" timestamptz,
    "input_hash" text,
    "output_path" text,
    "output_hash" text,
    "provider" text,
    "model" text,
    "prompt_version" text,
    "prompt_hash" text,
    "thinking_enabled" boolean,
    "reasoning_effort" text,
    "temperature" double precision,
    "input_tokens" bigint,
    "output_tokens" bigint,
    "reasoning_tokens" bigint,
    "cost_value" double precision,
    "cost_currency" text,
    "elapsed_seconds" double precision,
    "last_error_code" text,
    "last_error_message" text,
    "started_at" timestamptz,
    "completed_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("run_id","stage_name","unit_key")
);

CREATE INDEX "idx_taxonomy_stages_due" ON shiliu."taxonomy_stage_runs" ("workspace_id", "status", "next_retry_at");

CREATE TABLE shiliu."video_notes" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "video_id" bigint NOT NULL,
    "content" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "workspace_id" text NOT NULL,
    "owner_user_id" text NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "idx_video_notes_video" ON shiliu."video_notes" ("workspace_id", "video_id", "created_at", "id");

CREATE TABLE shiliu."video_source_memberships" (
    "source_id" bigint NOT NULL,
    "bvid" text NOT NULL,
    "video_id" bigint,
    "title" text NOT NULL DEFAULT '',
    "uploader" text NOT NULL DEFAULT '',
    "favorite_time" bigint,
    "source_position" bigint NOT NULL DEFAULT 0,
    "is_baseline" boolean NOT NULL DEFAULT false,
    "queued_history" boolean NOT NULL DEFAULT false,
    "first_observed_at" timestamptz NOT NULL,
    "last_observed_at" timestamptz NOT NULL,
    "removed_at" timestamptz,
    "workspace_id" text NOT NULL,
    "membership_seq" bigint NOT NULL,
    PRIMARY KEY ("source_id","bvid"),
    UNIQUE ("workspace_id","membership_seq")
);

CREATE INDEX "idx_memberships_history" ON shiliu."video_source_memberships" ("workspace_id", "queued_history", "source_id", "source_position");

CREATE INDEX "idx_memberships_video" ON shiliu."video_source_memberships" ("workspace_id", "video_id");

CREATE TABLE shiliu."videos" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "platform" text NOT NULL,
    "source_id" text NOT NULL,
    "part" bigint NOT NULL DEFAULT 1,
    "title" text NOT NULL,
    "uploader" text NOT NULL DEFAULT '',
    "description" text NOT NULL DEFAULT '',
    "description_links_json" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "video_url" text NOT NULL,
    "cover_url" text,
    "cover_path" text,
    "subtitle_language" text,
    "subtitle_source" text,
    "subtitle_upstream_type" bigint,
    "raw_subtitle_path" text,
    "transcript_path" text,
    "summary_path" text,
    "artifact_dir" text,
    "status" text NOT NULL,
    "error_code" text,
    "error_message" text,
    "subtitle_check_count" bigint NOT NULL DEFAULT 0,
    "subtitle_first_checked_at" timestamptz,
    "subtitle_next_check_at" timestamptz,
    "is_ignored" boolean NOT NULL DEFAULT false,
    "ignored_at" timestamptz,
    "discovered_at" timestamptz NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "completed_at" timestamptz,
    "removed_at" timestamptz,
    "processing_profile" text NOT NULL DEFAULT 'formal',
    "active_revision" text NOT NULL DEFAULT 'refined',
    "refinement_status" text NOT NULL DEFAULT 'not_required',
    "display_favorite_time" bigint,
    "duration_seconds" bigint NOT NULL DEFAULT 0,
    "page_count" bigint NOT NULL DEFAULT 1,
    "asr_provider" text,
    "asr_model" text,
    "reading_state" text NOT NULL DEFAULT 'unread',
    "reading_state_updated_at" timestamptz,
    "is_marked" boolean NOT NULL DEFAULT false,
    "marked_at" timestamptz,
    "archived_at" timestamptz,
    "published_at" bigint,
    "metadata_observed_at" timestamptz,
    "cid" bigint,
    "part_title" text NOT NULL DEFAULT '',
    "uploader_id" bigint,
    "workspace_id" text NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("workspace_id","platform","source_id","part"),
    UNIQUE ("workspace_id","id")
);

CREATE INDEX "idx_videos_status" ON shiliu."videos" ("workspace_id", "status");

CREATE TABLE shiliu."users" (
    "id" text NOT NULL,
    "display_name" text NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY ("id")
);

CREATE TABLE shiliu."workspaces" (
    "id" text NOT NULL,
    "kind" text NOT NULL,
    "owner_user_id" text NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY ("id"),
    UNIQUE ("id","owner_user_id"),
    CHECK (kind='personal')
);

CREATE TABLE shiliu."workspace_guards" (
    "workspace_id" text NOT NULL,
    "membership_highwater" bigint NOT NULL DEFAULT 0,
    "dependency_epoch" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("workspace_id"),
    CHECK (membership_highwater>=0),
    CHECK (dependency_epoch>=0)
);

